from flask import Blueprint, request, jsonify
from app.models.problem import Problem
from app.database import db

def problem_blueprint():
    problem_bp = Blueprint('problem', __name__)

    @problem_bp.route('/problems', methods=['GET'])
    def get_problems():
        try:
            problems = Problem.query.all()
            problem_list = [problem.to_dict() for problem in problems]
            return jsonify({"problems": problem_list}), 200
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    @problem_bp.route('/problems/<int:problem_id>', methods=['GET'])
    def get_problem(problem_id):
        try:
            problem = Problem.query.get(problem_id)
            if not problem:
                return jsonify({"error": "Problem not found"}), 404
            return jsonify(problem.to_dict()), 200
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    @problem_bp.route('/problems', methods=['POST'])
    def create_problem():
        try:
            data = request.get_json()
            new_problem = Problem(
                title=data.get('title'),
                description=data.get('description'),
                difficulty=data.get('difficulty'),
                tags=data.get('tags')
            )
            db.session.add(new_problem)
            db.session.commit()
            return jsonify(new_problem.to_dict()), 201
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    @problem_bp.route('/problems/<int:problem_id>', methods=['PUT'])
    def update_problem(problem_id):
        try:
            problem = Problem.query.get(problem_id)
            if not problem:
                return jsonify({"error": "Problem not found"}), 404
            data = request.get_json()
            problem.title = data.get('title', problem.title)
            problem.description = data.get('description', problem.description)
            problem.difficulty = data.get('difficulty', problem.difficulty)
            problem.tags = data.get('tags', problem.tags)
            db.session.commit()
            return jsonify(problem.to_dict()), 200
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    @problem_bp.route('/problems/<int:problem_id>', methods=['DELETE'])
    def delete_problem(problem_id):
        try:
            problem = Problem.query.get(problem_id)
            if not problem:
                return jsonify({"error": "Problem not found"}), 404
            db.session.delete(problem)
            db.session.commit()
            return jsonify({"message": "Problem deleted successfully"}), 200
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    return problem_bp

from flask import Blueprint, request, jsonify
from app.models.user import User
from app.database import db

def user_blueprint():
    user_bp = Blueprint('user', __name__)

    @user_bp.route('/users', methods=['GET'])
    def get_users():
        try:
            users = User.query.all()
            user_list = [{'id': user.id, 'username': user.username, 'email': user.email} for user in users]
            return jsonify(user_list), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @user_bp.route('/users/<int:user_id>', methods=['GET'])
    def get_user(user_id):
        try:
            user = User.query.get(user_id)
            if not user:
                return jsonify({'error': 'User not found'}), 404
            user_data = {'id': user.id, 'username': user.username, 'email': user.email}
            return jsonify(user_data), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @user_bp.route('/users', methods=['POST'])
    def create_user():
        try:
            data = request.get_json()
            username = data.get('username')
            email = data.get('email')
            if not username or not email:
                return jsonify({'error': 'Invalid input'}), 400
            new_user = User(username=username, email=email)
            db.session.add(new_user)
            db.session.commit()
            return jsonify({'message': 'User created successfully'}), 201
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 500

    @user_bp.route('/users/<int:user_id>', methods=['PUT'])
    def update_user(user_id):
        try:
            user = User.query.get(user_id)
            if not user:
                return jsonify({'error': 'User not found'}), 404
            data = request.get_json()
            username = data.get('username')
            email = data.get('email')
            if username:
                user.username = username
            if email:
                user.email = email
            db.session.commit()
            return jsonify({'message': 'User updated successfully'}), 200
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 500

    @user_bp.route('/users/<int:user_id>', methods=['DELETE'])
    def delete_user(user_id):
        try:
            user = User.query.get(user_id)
            if not user:
                return jsonify({'error': 'User not found'}), 404
            db.session.delete(user)
            db.session.commit()
            return jsonify({'message': 'User deleted successfully'}), 200
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 500

    return user_bp

from flask import Blueprint, request, jsonify
from app.models.solution import Solution
from app.database import db

def solution_blueprint():
    blueprint = Blueprint('solution', __name__)

    @blueprint.route('/submit_solution', methods=['POST'])
    def submit_solution():
        try:
            data = request.get_json()
            if not data or 'problem_id' not in data or 'user_id' not in data or 'code' not in data:
                return jsonify({'error': 'Invalid input'}), 400

            solution = Solution(
                problem_id=data['problem_id'],
                user_id=data['user_id'],
                code=data['code'],
                status="submitted"
            )
            db.session.add(solution)
            db.session.commit()

            return jsonify({'message': 'Solution submitted successfully', 'solution_id': solution.id}), 201

        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 500

    @blueprint.route('/get_solution/<int:solution_id>', methods=['GET'])
    def get_solution(solution_id):
        try:
            solution = Solution.query.get(solution_id)
            if not solution:
                return jsonify({'error': 'Solution not found'}), 404

            solution_data = {
                'id': solution.id,
                'problem_id': solution.problem_id,
                'user_id': solution.user_id,
                'code': solution.code,
                'status': solution.status,
                'created_at': solution.created_at,
                'updated_at': solution.updated_at
            }
            return jsonify(solution_data), 200

        except Exception as e:
            return jsonify({'error': str(e)}), 500

    return blueprint
